  '\\nWP-Cron only runs on visits and may be blocked by the host or a security plugin. Use "Test cron" or add a server cron job.\\n' => 'WP-Cron only runs on visits and may be blocked by the host or a security plugin. Use "Test cron" or add a server cron job.',
  '\\nNext scheduled:%s.\\n' => 'Next scheduled:%s.',
