  '\\nWooCommerce is active.\\n' => 'WooCommerce is active.',
  '\\nThe iyzico WooCommerce plugin is active: it takes one-time card payments, and Flux Donate reads its iyzico keys for monthly donations.\\n' => 'The iyzico WooCommerce plugin is active: it takes one-time card payments, and Flux Donate reads its iyzico keys for monthly donations.',
